/** Source facts and deterministic calculations; no trading or investment recommendations. */
final class Research {
 static final String IPO_PAGE=Repository.NSE+"/market-data/all-upcoming-issues-ipo";
 static final String GAIN="https://www.investorgain.com/report/ipo-gmp-live/331/",WATCH="https://ipowatch.in/ipo-grey-market-premium-latest-ipo-gmp/";
 static final class Feed<T>{String source="",stamp="",issue="";long fetched;boolean saved;List<T> rows=new ArrayList<>();void meta(Net.Result r){source=r.url;fetched=r.fetched;saved=r.saved;issue=r.issue;}}
 static final class Ipo {
  String symbol="",name="",series="",start="",end="",listing="",status="",range="",origin="";double price=Double.NaN,low=Double.NaN,high=Double.NaN,subscription=Double.NaN,bids=Double.NaN,offered=Double.NaN;long fetched;boolean saved;
  String id(){return symbol+"|"+start+"|"+end;}
  String phase(LocalDate today){if(!start.isEmpty()&&today.isBefore(LocalDate.parse(start)))return "Upcoming";if(!end.isEmpty()&&today.isAfter(LocalDate.parse(end)))return !listing.isEmpty()&&!today.isBefore(LocalDate.parse(listing))?"Listed":"Closed";if(!start.isEmpty()&&!end.isEmpty())return "Open by dates";return "Dates unavailable";}
  String url(){return Repository.NSE+"/market-data/issue-information?series="+Repository.encoded(series)+"&symbol="+Repository.encoded(symbol)+"&type="+("NSE upcoming".equals(origin)?"Upcoming":"Active");}
  JSONObject json()throws JSONException{JSONObject j=new JSONObject();j.put("symbol",symbol);j.put("name",name);j.put("series",series);j.put("start",start);j.put("end",end);j.put("listing",listing);j.put("status",status);j.put("range",range);j.put("origin",origin);j.put("fetched",fetched);put(j,"price",price);put(j,"low",low);put(j,"high",high);put(j,"subscription",subscription);put(j,"bids",bids);put(j,"offered",offered);return j;}
  static Ipo from(JSONObject j){Ipo i=new Ipo();i.symbol=Parse.str(j,"symbol");i.name=Parse.str(j,"name");i.series=Parse.str(j,"series");i.start=Parse.str(j,"start");i.end=Parse.str(j,"end");i.listing=Parse.str(j,"listing");i.status=Parse.str(j,"status");i.range=Parse.str(j,"range");i.origin=Parse.str(j,"origin");i.fetched=j.optLong("fetched");i.price=Parse.number(j.opt("price"));i.low=Parse.number(j.opt("low"));i.high=Parse.number(j.opt("high"));i.subscription=Parse.number(j.opt("subscription"));i.bids=Parse.number(j.opt("bids"));i.offered=Parse.number(j.opt("offered"));i.saved=true;return i;}
 }
 static void put(JSONObject j,String key,double d)throws JSONException{if(Double.isFinite(d))j.put(key,d);}
 static double firstNumber(String text){if(text==null)return Double.NaN;Matcher m=Pattern.compile("[-+]?\\d[\\d,]*(?:\\.\\d+)?").matcher(text);return m.find()?Parse.number(m.group()):Double.NaN;}
 static double[] band(String text){List<Double> n=new ArrayList<>();Matcher m=Pattern.compile("\\d[\\d,]*(?:\\.\\d+)?").matcher(text);while(m.find()&&n.size()<3)n.add(Parse.number(m.group()));if(n.size()==1)return new double[]{n.get(0),n.get(0)};if(n.size()==2&&n.get(1)>=n.get(0))return new double[]{n.get(0),n.get(1)};return new double[]{Double.NaN,Double.NaN};}
 static Feed<Ipo> issues(String raw,String kind)throws Exception{Object parsed=new JSONTokener(raw).nextValue();JSONArray data=parsed instanceof JSONArray?(JSONArray)parsed:parsed instanceof JSONObject?((JSONObject)parsed).optJSONArray("data"):null;if(data==null)throw new IOException("Unrecognized NSE IPO format");Feed<Ipo> out=new Feed<>();out.source="NSE "+kind;for(int n=0;n<data.length();n++){JSONObject j=data.optJSONObject(n);if(j==null)continue;Ipo i=new Ipo();i.symbol=Data.symbol(Parse.str(j,"symbol"));i.name=Parse.str(j,"companyName");if(i.name.isEmpty())i.name=Parse.str(j,"company");if(!Data.validSymbol(i.symbol)||i.name.isEmpty())continue;i.series=Parse.str(j,"series");if(i.series.isEmpty())i.series=Parse.str(j,"securityType");i.start=Parse.canonical(Parse.str(j,"issueStartDate"));if(i.start.isEmpty())i.start=Parse.canonical(Parse.str(j,"ipoStartDate"));i.end=Parse.canonical(Parse.str(j,"issueEndDate"));if(i.end.isEmpty())i.end=Parse.canonical(Parse.str(j,"ipoEndDate"));i.listing=Parse.canonical(Parse.str(j,"listingDate"));i.status=Parse.str(j,"status");i.range=Parse.str(j,"priceRange");double[] b=band(i.range);i.low=b[0];i.high=b[1];i.price=Parse.number(j.opt("issuePrice"));i.subscription=Parse.number(j.opt("noOfTime"));i.bids=Parse.number(j.opt("noOfsharesBid"));i.offered=Parse.number(j.opt("noOfSharesOffered"));i.origin="NSE "+kind;out.rows.add(i);}if(data.length()>0&&out.rows.isEmpty())throw new IOException("IPO response contains no recognized issuers");return out;}
 static List<Ipo> merge(List<Feed<Ipo>> feeds){Map<String,Ipo> map=new LinkedHashMap<>();for(Feed<Ipo> feed:feeds)for(Ipo row:feed.rows){Ipo old=map.get(row.id());if(old==null){map.put(row.id(),row);continue;}if(old.range.isEmpty())old.range=row.range;if(!Double.isFinite(old.high)){old.high=row.high;old.low=row.low;}if(!Double.isFinite(old.price))old.price=row.price;if(old.listing.isEmpty())old.listing=row.listing;if(!Double.isFinite(old.subscription))old.subscription=row.subscription;if(!Double.isFinite(old.bids))old.bids=row.bids;if(!Double.isFinite(old.offered))old.offered=row.offered;if(old.status.isEmpty())old.status=row.status;}List<Ipo> all=new ArrayList<>(map.values());all.sort((a,b)->b.start.compareTo(a.start));return all;}
 static final class IssueInfo {Map<String,String> facts=new LinkedHashMap<>();List<String[]> bids=new ArrayList<>();String stamp="",source="",issue="";long fetched;boolean saved;double lot=Double.NaN,low=Double.NaN,high=Double.NaN;}
 static IssueInfo issueInfo(String raw,String symbol)throws Exception{JSONObject j=new JSONObject(raw);String reported=Parse.str(j,"companyName");JSONObject info=j.optJSONObject("issueInfo");JSONArray rows=info==null?null:info.optJSONArray("dataList");if(rows==null)throw new IOException("No issue information returned");IssueInfo out=new IssueInfo();String identity="";Set<String> useful=new HashSet<>(Arrays.asList("Symbol","Issue Period","Issue Size","Issue Type","Price Range","Lot Size","Face Value","IPO Market Timings","Book Running Lead Managers","Name of the Registrar","Registrar to the Issue","Sponsor Bank"));for(int n=0;n<rows.length();n++){JSONObject row=rows.getJSONObject(n);String title=Parse.str(row,"title"),value=clean(Parse.str(row,"value"));if(title.equals("Symbol"))identity=value;if(useful.contains(title)&&!value.isEmpty())out.facts.put(title,value);if(title.equals("Lot Size"))out.lot=firstNumber(value);if(title.equals("Price Range")){double[] b=band(value);out.low=b[0];out.high=b[1];}}if(!symbol.equalsIgnoreCase(identity.isEmpty()?reported:identity))throw new IOException("Issue information did not match the selected symbol");out.stamp=Parse.str(j,"updateTime");JSONArray bids=j.optJSONArray("bidDetails");if(bids!=null)for(int n=0;n<bids.length();n++){JSONObject row=bids.getJSONObject(n);String sr=Parse.str(row,"srNo"),category=Parse.str(row,"category");if(sr.matches("[0-9]+")||category.equalsIgnoreCase("Total"))out.bids.add(new String[]{category,Parse.str(row,"noOfshareBid"),Parse.str(row,"noofapplication")});}return out;}
 static final class Gmp {String name="",provider="",url="",stamp="",open="",close="",listing="",board="",dates="";double premium=Double.NaN,price=Double.NaN,lot=Double.NaN;String id(){return provider+"|"+url;}double estimated(){return Double.isFinite(premium)&&Double.isFinite(price)&&price>0?price+premium:Double.NaN;}double percent(){return Double.isFinite(premium)&&Double.isFinite(price)&&price>0?premium/price*100:Double.NaN;}JSONObject json()throws JSONException{JSONObject j=new JSONObject();j.put("name",name);j.put("provider",provider);j.put("url",url);j.put("stamp",stamp);j.put("open",open);j.put("close",close);j.put("listing",listing);j.put("board",board);j.put("dates",dates);put(j,"premium",premium);put(j,"price",price);put(j,"lot",lot);return j;}}
 static String clean(String html){String s=html.replaceAll("(?is)<(?:script|style)\\b[^>]*>.*?</(?:script|style)>"," ").replaceAll("(?is)<br\\s*/?>","\n").replaceAll("(?s)<[^>]*>"," ");s=s.replace("&amp;","&").replace("&nbsp;"," ").replace("&quot;","\"").replace("&#39;","'").replace("&lt;","<").replace("&gt;",">");Matcher m=Pattern.compile("&#(x[0-9a-fA-F]+|[0-9]+);").matcher(s);StringBuffer result=new StringBuffer();while(m.find()){String v=m.group(1);String replacement="";try{int code=Integer.parseInt(v.startsWith("x")?v.substring(1):v,v.startsWith("x")?16:10);if(Character.isValidCodePoint(code))replacement=new String(Character.toChars(code));}catch(Exception ignored){}m.appendReplacement(result,Matcher.quoteReplacement(replacement));}m.appendTail(result);return result.toString().replaceAll("[\\t\\r ]+"," ").replaceAll(" *\n *","\n").trim();}
 static List<String> cells(String row){List<String> out=new ArrayList<>();Matcher m=Pattern.compile("(?is)<t[dh]\\b[^>]*>(.*?)</t[dh]>").matcher(row);while(m.find())out.add(m.group(1));return out;}
 static String href(String cell,String base){Matcher m=Pattern.compile("(?i)href=[\"']([^\"']+)[\"']").matcher(cell);if(!m.find())return "";try{URI u=new URI(base).resolve(m.group(1).replace("&amp;","&"));String h=u.getHost(),expected=new URI(base).getHost();return "https".equals(u.getScheme())&&u.getUserInfo()==null&&h!=null&&h.equals(expected)?u.toString():"";}catch(Exception e){return "";}}
 static Feed<Gmp> gmp(String html,String provider)throws Exception{Feed<Gmp> feed=new Feed<>();boolean gain=provider.equals("InvestorGain");String base=gain?"https://www.investorgain.com":"https://ipowatch.in";feed.source=gain?GAIN:WATCH;Matcher modified=Pattern.compile("\"dateModified\"\\s*:\\s*\"([^\"]+)\"").matcher(html);if(modified.find())feed.stamp=modified.group(1);Matcher tables=Pattern.compile("(?is)<table\\b[^>]*>.*?</table>").matcher(html);Set<String> seen=new HashSet<>();boolean recognized=false;while(tables.find()){String table=tables.group();List<String> headers=new ArrayList<>();Matcher row=Pattern.compile("(?is)<tr\\b[^>]*>.*?</tr>").matcher(table);while(row.find()){List<String> c=cells(row.group());if(c.isEmpty())continue;if(headers.isEmpty()){if(!row.group().toLowerCase(Locale.ROOT).contains("<th"))continue;for(String cell:c)headers.add(Parse.header(clean(cell)));if(headers.stream().noneMatch(h->h.startsWith("gmp"))){headers.clear();continue;}recognized=true;continue;}int name=index(headers,gain?"name":"company"),gmp=index(headers,"gmp"),price=index(headers,gain?"price":"priceband");if(name<0||gmp<0||price<0||c.size()<headers.size())continue;String url=href(c.get(name),base);if(url.isEmpty()||!seen.add(url))continue;Gmp q=new Gmp();q.provider=provider;q.url=url;Matcher a=Pattern.compile("(?is)<a\\b[^>]*>(.*?)</a>").matcher(c.get(name));if(!a.find())continue;q.name=clean(a.group(1));String g=clean(c.get(gmp)).split("\n",2)[0].trim();q.premium=g.contains("--")||g.equals("-")?Double.NaN:firstNumber(g);double[] priceBand=band(clean(c.get(price)));q.price=priceBand[1];q.lot=value(c,headers,"lot");q.stamp=text(c,headers,"updatedon");q.open=firstLine(text(c,headers,"open"));q.close=firstLine(text(c,headers,"close"));q.listing=firstLine(text(c,headers,"listing"));q.dates=firstLine(text(c,headers,"date"));q.board=clean(c.get(name)).replace(q.name,"").trim();feed.rows.add(q);}}if(!recognized)throw new IOException("The publisher's GMP table format is unavailable");if(feed.rows.isEmpty())throw new IOException("No publisher GMP rows were recognized");return feed;}
 static int index(List<String> h,String name){for(int n=0;n<h.size();n++)if(h.get(n).equals(name)||name.equals("gmp")&&h.get(n).startsWith("gmp")||name.equals("price")&&h.get(n).startsWith("price"))return n;return -1;}
 static String text(List<String> cells,List<String> headers,String key){int index=index(headers,key);return index<0||index>=cells.size()?"":clean(cells.get(index));}static double value(List<String> cells,List<String> h,String key){return firstNumber(text(cells,h,key));}static String firstLine(String s){return s.split("\n",2)[0].trim();}
 static double change(double now,double before){return Double.isFinite(now)&&Double.isFinite(before)&&before>0?(now-before)/before*100:Double.NaN;}
 static double percentagePoints(double now,double before){return Double.isFinite(now)&&Double.isFinite(before)?now-before:Double.NaN;}
 static double lotCost(double price,double shares,double lots){if(!Double.isFinite(price)||!Double.isFinite(shares)||!Double.isFinite(lots)||price<=0||shares<=0||lots<1||lots!=Math.floor(lots)||shares!=Math.floor(shares))return Double.NaN;double value=price*shares*lots;return Double.isFinite(value)?value:Double.NaN;}
 static final class Position {String symbol="",name="";double quantity=Double.NaN,average=Double.NaN,fees=0;double cost(){return quantity*average+fees;}double value(double price){return Double.isFinite(price)&&price>0?quantity*price:Double.NaN;}double pnl(double price){return value(price)-cost();}JSONObject json()throws JSONException{JSONObject j=new JSONObject();j.put("symbol",symbol);j.put("name",name);j.put("quantity",quantity);j.put("average",average);j.put("fees",fees);return j;}static Position from(JSONObject j){Position p=new Position();if(j==null)return p;p.symbol=Parse.str(j,"symbol");p.name=Parse.str(j,"name");p.quantity=Parse.number(j.opt("quantity"));p.average=Parse.number(j.opt("average"));p.fees=Parse.number(j.opt("fees"));return p;}boolean valid(){return Data.validSymbol(symbol)&&Double.isFinite(quantity)&&quantity>0&&quantity==Math.floor(quantity)&&Double.isFinite(average)&&average>=0&&Double.isFinite(fees)&&fees>=0&&Double.isFinite(cost());}}
 static final class Event {String title="",date="",url="",record="",kind="";}
 static List<Event> events(String raw,boolean actions,String symbol)throws Exception{JSONArray a=new JSONArray(raw);List<Event> out=new ArrayList<>();for(int n=0;n<a.length();n++){JSONObject j=a.getJSONObject(n);if(!symbol.equalsIgnoreCase(Parse.str(j,"symbol")))continue;Event e=new Event();e.kind=actions?"Corporate action":"Company filing";e.title=actions?Parse.str(j,"subject"):Parse.str(j,"desc");e.date=actions?Parse.str(j,"exDate"):Parse.str(j,"an_dt");e.record=actions?Parse.str(j,"recDate"):"";e.url=actions?"":Parse.str(j,"attchmntFile");if(!e.title.isEmpty())out.add(e);}return out;}
}
